

'use client';

import { useState, useEffect, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/context/auth-context';
import { useRouter } from 'next/navigation';
import { useToast } from '@/hooks/use-toast';
import { Loader2, ShieldCheck } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

const loginSchema = z.object({
  email: z.string().email({ message: 'Please enter a valid email address.' }),
  password: z.string().min(1, { message: 'Password is required.' }),
});

const GoogleIcon = (props: React.SVGProps<SVGSVGElement>) => (
    <svg role="img" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" {...props}>
        <path d="M12.48 10.92v3.28h7.84c-.24 1.84-.85 3.18-1.73 4.1-1.02 1.02-2.62 1.96-4.66 1.96-3.88 0-7.04-3.16-7.04-7.04s3.16-7.04 7.04-7.04c2.28 0 4.07.88 4.96 1.76l2.54-2.54C19.6 1.96 16.46 0 12.48 0 5.88 0 .02 5.88.02 12.48s5.86 12.48 12.46 12.48c3.34 0 6.03-1.12 8.01-3.12 2.05-2.05 2.72-5.06 2.72-8.24 0-.76-.07-1.52-.2-2.26h-10.5z" />
    </svg>
);

const BlueprintBackground = () => (
  <div
    className="absolute inset-0 z-0 bg-cover bg-center bg-no-repeat"
    style={{
      backgroundImage: `url('/login-bg.png')`,
    }}
  >
    <div 
        className="absolute inset-0 z-0 bg-contain bg-center bg-no-repeat opacity-10"
        style={{}}
    />
  </div>
);

export default function LoginPage() {
  const { user, userProfile, isSuperAdmin, logIn, signInWithGoogle, sendPasswordReset, sendVerificationEmail } = useAuth();
  const [isEmailLoading, setIsEmailLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [showVerificationAlert, setShowVerificationAlert] = useState(false);
  const router = useRouter();
  const { toast } = useToast();
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Cleanup timeout on component unmount
  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  const onLoginSubmit = async (values: z.infer<typeof loginSchema>) => {
    if (isEmailLoading || isGoogleLoading) return;
    setIsEmailLoading(true);

    // Set a 30-second timeout as a safety net
    timeoutRef.current = setTimeout(() => {
        setIsEmailLoading(false);
        toast({
            variant: 'destructive',
            title: 'Request Timed Out',
            description: 'The login attempt took too long. Please check your network or if the domain is authorized in Firebase.',
        });
    }, 30000);

    try {
      const userCredential = await logIn(values.email, values.password);
      if (userCredential && !userCredential.emailVerified) {
          // The isSuperAdmin check will be handled in the useEffect below
          setShowVerificationAlert(true);
      } else {
          router.push('/');
      }
    } catch (error: any) {
      toast({
        variant: 'destructive',
        title: 'Login Failed',
        description: error.message || 'An unexpected error occurred. Please check your credentials or internet connection.',
      });
    } finally {
        if (timeoutRef.current) {
            clearTimeout(timeoutRef.current);
        }
        setIsEmailLoading(false);
    }
  };

  useEffect(() => {
    // This effect runs after login state is updated
    if (user && userProfile) {
        if (user.emailVerified || isSuperAdmin) {
            router.push('/');
        } else {
            setShowVerificationAlert(true);
        }
    }
  }, [user, userProfile, isSuperAdmin, router]);


  const handleGoogleSignIn = async () => {
    if (isEmailLoading || isGoogleLoading) return;
    setIsGoogleLoading(true);
    try {
        await signInWithGoogle();
        // The useEffect will handle redirection after google sign in
    } catch (error: any) {
        // Error handling is now done inside the signInWithGoogle function in auth-context
    } finally {
        setIsGoogleLoading(false);
    }
  }

  const handleForgotPassword = async () => {
    const email = loginForm.getValues('email');
    if (!email) {
      toast({
        variant: 'destructive',
        title: 'Email Required',
        description: 'Please enter your email address in the email field first.',
      });
      loginForm.setFocus('email');
      return;
    }

    try {
      await sendPasswordReset(email);
      toast({
        title: 'Password Reset Email Sent',
        description: `An email has been sent to ${email} with instructions to reset your password.`,
      });
    } catch (error: any) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: error.message || 'Could not send password reset email. Please try again.',
      });
    }
  };

  const handleResendVerification = async () => {
      if (!user) return;
      try {
          await sendVerificationEmail(user);
          toast({
              title: 'Verification Email Sent',
              description: 'A new verification link has been sent to your email address.',
          });
      } catch (error: any) {
           toast({
              variant: 'destructive',
              title: 'Error Sending Email',
              description: error.message || 'Could not send verification email. Please try again later.',
          });
      }
  }
  
  const loginForm = useForm<z.infer<typeof loginSchema>>({
    resolver: zodResolver(loginSchema),
    defaultValues: { email: '', password: '' },
  });


  return (
    <>
    <div className="relative flex min-h-screen flex-col items-center justify-center p-4 bg-white">
       <BlueprintBackground />
       <div className="mb-8 text-center z-10">
        <h1 className="text-5xl font-bold text-gray-800">Inventra</h1>
      </div>
      <Card className="w-full max-w-sm z-10 rounded-[10px] bg-neutral-100/95 backdrop-blur-sm shadow-soft border-black">
        <CardHeader className="text-center">
          <CardTitle className="text-2xl font-bold">Welcome Back!</CardTitle>
          <CardDescription>Sign in to your account to continue.</CardDescription>
        </CardHeader>
        <CardContent>
            {showVerificationAlert && (
                <Alert variant="destructive" className="mb-4">
                    <ShieldCheck className="h-4 w-4" />
                    <AlertTitle>Email Verification Required</AlertTitle>
                    <AlertDescription>
                        Please check your inbox to verify your email address. 
                        <Button variant="link" className="p-0 h-auto ml-1" onClick={handleResendVerification}>
                            Resend verification email
                        </Button>
                    </AlertDescription>
                </Alert>
            )}
            <Form {...loginForm}>
                <form onSubmit={loginForm.handleSubmit(onLoginSubmit)} className="space-y-4">
                <fieldset disabled={isEmailLoading || isGoogleLoading}>
                    <FormField control={loginForm.control} name="email" render={({ field }) => (
                        <FormItem><FormLabel className="font-bold">Email</FormLabel><FormControl><Input className="focus:ring-primary/80" type="email" placeholder="name@example.com" {...field} /></FormControl><FormMessage /></FormItem>
                    )} />
                    <FormField control={loginForm.control} name="password" render={({ field }) => (
                        <FormItem>
                          <div className="flex items-center justify-between">
                            <FormLabel className="font-bold">Password</FormLabel>
                             <a href="#" className="text-xs text-primary hover:underline" onClick={(e) => { e.preventDefault(); handleForgotPassword(); }}>
                              Forgot password?
                            </a>
                          </div>
                          <FormControl><Input className="focus:ring-primary/80" type="password" placeholder="••••••••" {...field} /></FormControl><FormMessage />
                        </FormItem>
                    )} />
                </fieldset>
                <Button
                 type="submit" 
                 className="w-full !mt-6 text-primary-foreground font-bold bg-gradient-to-b from-amber-400 to-amber-500 border-b-4 border-amber-700 shadow-lg transform transition-transform duration-100 ease-in-out active:translate-y-1 active:border-b-0 active:shadow-none"
                 disabled={isEmailLoading || isGoogleLoading}
                 aria-disabled={isEmailLoading}
                 aria-busy={isEmailLoading}
                >
                    {isEmailLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    {isEmailLoading ? 'Signing In...' : 'Sign In'}
                </Button>
                </form>
            </Form>
            
            <div className="relative my-6">
                <div className="absolute inset-0 flex items-center">
                    <span className="w-full border-t" />
                </div>
                <div className="relative flex justify-center text-xs uppercase">
                    <span className="bg-neutral-100 px-2 text-muted-foreground">
                    Or continue with
                    </span>
                </div>
            </div>

            <Button variant="outline" className="w-full" onClick={handleGoogleSignIn} disabled={isEmailLoading || isGoogleLoading}>
                {isGoogleLoading ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                    <GoogleIcon className="mr-2 h-4 w-4" />
                )}
                Sign in with Google
            </Button>
            <p className="mt-4 text-center text-xs text-muted-foreground">
                Don't have an account?{' '}
                <a href="#" className="underline" onClick={(e) => { e.preventDefault(); router.push('/signup'); }}>
                    Create one
                </a>
            </p>
        </CardContent>
      </Card>
    </div>
    </>
  );
}
